insert into public.posts
  (author_name, org, category, title, content, visibility, source, source_url, created_at)
select e->>0, 'YB', e->>1, e->>2,
       case when (e->>3) <> '' then (e->>3) || chr(10) || chr(10) else '' end
       || '(구)도쿄대학 한국인 학생회 홈페이지 「' || lab.name || '」 에서 옮겨온 글입니다.'
       || chr(10) || '원문 보기 : ' || (e->>5),
       e->>4, 'legacy', e->>5, (e->>6)::timestamptz
  from src join lab on lab.i = (e->>7)::int
 where not exists (select 1 from public.posts p
                    where p.org = 'YB' and p.source_url = e->>5);
